import { ComponentFixture, inject, TestBed } from "@angular/core/testing";

import { FormComponent } from "./form.component";
import {
  HttpTestingController,
  provideHttpClientTesting,
} from "@angular/common/http/testing";
import { FormBuilder, Validators } from "@angular/forms";
import { of, throwError } from "rxjs";
import { TestingService } from "../../services/testing.service";
import { provideHttpClient } from "@angular/common/http";
import { environment } from "../../../environments/environment";

describe("FormComponent", () => {
  let component: FormComponent;
  let fixture: ComponentFixture<FormComponent>;
  let httpTestingController: HttpTestingController;
  let testingService: TestingService;

  const userMock = { name: "name", email: "email", password: "password" };
  const errorCodes = [
    "SFB0000",
    "SFB0001",
    "SFB0002",
    "SFB0003",
    "SFB0004",
    "SFB0005",
    "SFB0006",
    "SFB0007",
  ];

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [FormComponent],
      providers: [provideHttpClient(), provideHttpClientTesting()],
    }).compileComponents();

    fixture = TestBed.createComponent(FormComponent);
    component = fixture.componentInstance;
    httpTestingController = TestBed.inject(HttpTestingController);
    testingService = TestBed.inject(TestingService);

    fixture.detectChanges();
  });

  afterEach(() => {
    httpTestingController.verify();
  });

  it("should create", () => {
    expect(component).toBeTruthy();
  });

  it("should regist user success", () => {
    spyOn(testingService, "validateUser").and.callThrough();

    component.form.setValue({
      name: "name",
      email: "email@email.com",
      password: "password",
    });

    component.submited$.next();

    const req = httpTestingController.expectOne("api/validateUser");
    expect(req.request.method).toBe("POST");
    req.flush(userMock);

    expect(component.albums).toEqual(userMock);
    expect(component["loading"]).toEqual(false);
  });

  it("should handle errors", () => {
    spyOn(testingService, "validateUser").and.callThrough();

    component.form.setValue({
      name: "name",
      email: "email@email.com",
      password: "password",
    });

    component.submited$.next();

    const req = httpTestingController.expectOne("api/validateUser");
    expect(req.request.method).toBe("POST");

    errorCodes.forEach((code) => {
      const errorMock = { listErrorDto: { code } };
      req.flush(errorMock);
      expect(component["loading"]).toEqual(false);
      const codeType = code as keyof typeof environment.errorMessages;
      const expectedMessage =
        environment.errorMessages[codeType] || "Error desconocido";
      expect(component.albums).toEqual(expectedMessage);
    });
  });
});
